    },
    {
      "campo": "resolucao.antes.simbolos",
      "depois": [
        ["protozoose", "doença causada por protozoário (ser vivo de uma célula só)"],
        ["agente etiológico", "o organismo que causa a doença"],
        ["hospedeiro", "ser vivo que abriga o parasita"],
        ["divisão binária", "reprodução assexuada em que uma célula origina duas iguais"],
        ["assexuada", "reprodução sem gametas e sem fecundação"],
        ["gameta", "célula sexual (óvulo, espermatozoide) que se une na fecundação"],
        ["esporo", "célula de resistência ou de reprodução, típica do Plasmodium (malária) e de fungos"],
        ["eritrócito", "hemácia, a célula vermelha do sangue"],
        ["amastigota", "forma do parasita sem flagelo livre, que se multiplica dentro das células humanas"],
        ["epimastigota", "forma do parasita que se multiplica no intestino do inseto"],
        ["tripomastigota", "forma com flagelo, que circula no sangue ou é eliminada nas fezes do inseto e infecta"]
      ],
      "motivo": "Os passos usam epimastigota, tripomastigota, hospedeiro e assexuada, que não estavam explicados."
    },
    {
      "campo": "resolucao.antes.formulas",
      "depois": [
        "Inseto (barbeiro): epimastigota se divide no intestino → tripomastigota infectante nas fezes",
        "Humano: tripomastigota entra na célula → vira amastigota, que se divide → vira tripomastigota → cai no sangue",
        "Reprodução do T. cruzi = divisão binária (assexuada)"
      ],
      "motivo": "Troca 'metacíclico' por 'infectante', palavra simples."
